after.content:
  submitByEnter(desktopPage, "desktop queued"),
  submitByEnter(phonePage, "phone queued"),
])
await expect.poll(async () => {
  const commandErrors = await Promise.all([
    desktopPage.locator("[data-error-code]").allTextContents(),
    phonePage.locator("[data-error-code]").allTextContents(),
  ])
  if (commandErrors.flat().length) {
    throw new Error(`concurrent prompt failed: ${commandErrors.flat().join(", ")}`)
  }
  return (await canonicalState(probePort)).queue.length
}).toBe(2)
const initialQueue = (await canonicalState(probePort)).queue
expect(initialQueue.map(item => item.order)).toEqual([0, 1])
expect(new Set(initialQueue.map(item => item.acceptedSeq)).size).toBe(2)
